// tokenbucket.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for testing.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// NewTokenBucket creates a full bucket. capacity is in tokens; rate is tokens/sec.
func NewTokenBucket(capacity int, rate float64, clock Clock) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	now := clock.Now()
	return &TokenBucket{
		capacity: float64(capacity),
		tokens:   float64(capacity),
		rate:     rate,
		last:     now,
		clock:    clock,
	}, nil
}

// NewTokenBucketReal creates a bucket using the system clock.
func NewTokenBucketReal(capacity int, rate float64) (*TokenBucket, error) {
	return NewTokenBucket(capacity, rate, realClock{})
}

// AllowN reports whether n tokens can be consumed, consuming them if so.
func (b *TokenBucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	if n == 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refill()
	if float64(n) > b.capacity {
		return false
	}
	if float64(n) > b.tokens {
		return false
	}
	b.tokens -= float64(n)
	return true
}

// Allow reports whether one token can be consumed.
func (b *TokenBucket) Allow() bool {
	return b.AllowN(1)
}

// Tokens returns the current available token count (for observability).
func (b *TokenBucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refill()
	return b.tokens
}

func (b *TokenBucket) refill() {
	now := b.clock.Now()
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}
